import{_ as n,o as e,c as t,a2 as i}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Pengumuman","description":"","frontmatter":{"title":"Pengumuman","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/pengumuman.md","filePath":"latest/pengumuman.md","lastUpdated":1786334463000}'),u={name:"latest/pengumuman.md"};function r(m,a,l,o,g,s){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="pengumuman" tabindex="-1">Pengumuman <a class="header-anchor" href="#pengumuman" aria-label="Permalink to &quot;Pengumuman&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul <strong>Pengumuman</strong> menampilkan informasi resmi dari komunitas ILUNI FT ELEKTRO UNPAK, seperti pencapaian anggota, informasi lowongan, undangan event, dan kabar umum. Pengumuman dikategorikan agar mudah disaring.</p><h2 id="melihat-daftar-pengumuman" tabindex="-1">Melihat Daftar Pengumuman <a class="header-anchor" href="#melihat-daftar-pengumuman" aria-label="Permalink to &quot;Melihat Daftar Pengumuman&quot;">​</a></h2><ol><li>Klik menu <strong>Pengumuman</strong> pada navigasi.</li><li>Halaman menampilkan daftar pengumuman terbaru dengan informasi: <ul><li>Judul dan isi ringkas.</li><li>Kategori pengumuman.</li><li>Penulis dan tanggal penerbitan.</li></ul></li><li>Klik pengumuman untuk membaca isi lengkapnya.</li></ol><h2 id="kategori-pengumuman" tabindex="-1">Kategori Pengumuman <a class="header-anchor" href="#kategori-pengumuman" aria-label="Permalink to &quot;Kategori Pengumuman&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kategori</th><th>Isi</th></tr></thead><tbody><tr><td><strong>Pencapaian</strong></td><td>Prestasi dan pencapaian anggota atau komunitas.</td></tr><tr><td><strong>Lowongan</strong></td><td>Informasi lowongan kerja dari anggota.</td></tr><tr><td><strong>Event</strong></td><td>Undangan dan informasi kegiatan/event.</td></tr><tr><td><strong>Umum</strong></td><td>Informasi lain yang bersifat umum.</td></tr></tbody></table><h3 id="menyaring-berdasarkan-kategori" tabindex="-1">Menyaring Berdasarkan Kategori <a class="header-anchor" href="#menyaring-berdasarkan-kategori" aria-label="Permalink to &quot;Menyaring Berdasarkan Kategori&quot;">​</a></h3><ol><li>Buka halaman <strong>Pengumuman</strong>.</li><li>Gunakan filter <strong>kategori</strong> di bagian atas halaman.</li><li>Pilih kategori untuk hanya menampilkan pengumuman yang sesuai.</li></ol><h2 id="membuat-pengumuman" tabindex="-1">Membuat Pengumuman <a class="header-anchor" href="#membuat-pengumuman" aria-label="Permalink to &quot;Membuat Pengumuman&quot;">​</a></h2><p>Membuat pengumuman hanya tersedia untuk <strong>alumni yang profilnya sudah terverifikasi</strong>.</p><h3 id="membuka-formulir" tabindex="-1">Membuka Formulir <a class="header-anchor" href="#membuka-formulir" aria-label="Permalink to &quot;Membuka Formulir&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk dan profil terverifikasi.</li><li>Klik tombol <strong>Buat Pengumuman</strong> pada halaman <strong>Pengumuman</strong>.</li><li>Anda akan diarahkan ke halaman pembuatan pengumuman.</li></ol><h3 id="mengisi-formulir" tabindex="-1">Mengisi Formulir <a class="header-anchor" href="#mengisi-formulir" aria-label="Permalink to &quot;Mengisi Formulir&quot;">​</a></h3><ol><li>Pilih <strong>kategori</strong> pengumuman.</li><li>Isi <strong>judul</strong> pengumuman.</li><li>Tulis <strong>isi</strong> pengumuman.</li><li>Klik <strong>Simpan</strong>.</li></ol><h3 id="setelah-menerbitkan" tabindex="-1">Setelah Menerbitkan <a class="header-anchor" href="#setelah-menerbitkan" aria-label="Permalink to &quot;Setelah Menerbitkan&quot;">​</a></h3><p>Pengumuman langsung tampil di halaman <strong>Pengumuman</strong> dan dapat dibaca seluruh pengguna.</p><h2 id="menghapus-pengumuman" tabindex="-1">Menghapus Pengumuman <a class="header-anchor" href="#menghapus-pengumuman" aria-label="Permalink to &quot;Menghapus Pengumuman&quot;">​</a></h2><p>Pengumuman dapat dihapus oleh:</p><ul><li><strong>Penulis</strong> pengumuman.</li><li><strong>Admin</strong> dengan kemampuan <code>moderate_announcements</code>.</li><li><strong>Super admin</strong>.</li></ul><ol><li>Buka halaman detail pengumuman.</li><li>Klik tombol <strong>Hapus</strong> (jika tersedia untuk Anda).</li><li>Konfirmasi penghapusan.</li></ol><h2 id="tips-menulis-pengumuman" tabindex="-1">Tips Menulis Pengumuman <a class="header-anchor" href="#tips-menulis-pengumuman" aria-label="Permalink to &quot;Tips Menulis Pengumuman&quot;">​</a></h2><ul><li>Gunakan judul yang jelas dan informatif.</li><li>Cantumkan tanggal, waktu, dan tempat untuk pengumuman event.</li><li>Pilih kategori yang paling sesuai agar mudah ditemukan.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/polling">Polling</a> untuk berpartisipasi dalam jajak pendapat.</p>',24)])])}const p=n(u,[["render",r]]);export{h as __pageData,p as default};
